CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role text NOT NULL DEFAULT 'owner', UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own studio role" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.is_studio_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'owner') $$;
REVOKE ALL ON FUNCTION public.is_studio_owner() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_studio_owner() TO authenticated;
CREATE FUNCTION public.enroll_studio_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF lower(NEW.email) = 'divineeribo8@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id, role) VALUES (NEW.id, 'owner') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER enroll_studio_owner AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.enroll_studio_owner();
DROP POLICY "Authenticated owners can manage portfolio items" ON public.portfolio_items;
CREATE POLICY "Studio owner manages portfolio" ON public.portfolio_items FOR ALL TO authenticated USING (public.is_studio_owner()) WITH CHECK (public.is_studio_owner());
CREATE POLICY "Signed in visitors see published work" ON public.portfolio_items FOR SELECT TO authenticated USING (published = true);
GRANT SELECT ON public.portfolio_items TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.portfolio_items TO authenticated;
GRANT ALL ON public.portfolio_items TO service_role;
CREATE POLICY "Studio owner manages media" ON storage.objects FOR ALL TO authenticated USING (bucket_id = 'portfolio-media' AND public.is_studio_owner()) WITH CHECK (bucket_id = 'portfolio-media' AND public.is_studio_owner());
DROP POLICY "Authenticated users can read their selected inspiration files" ON storage.objects;
CREATE POLICY "Studio owner reads inspiration" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'booking-inspiration' AND public.is_studio_owner());